# WAR ARENA - Balance + Free Quota + Pricing v2 (packs + COMMAND tier) - Installer
# Merges: BalanceLedger (atomic debit, no double-spend, refund), 3 free scans,
# credit packs, WAR COMMAND $1000 tier. Run from project root:
#   powershell -ExecutionPolicy Bypass -File .\install-balance.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Balance + Pricing v2 installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/product/payment/balance.ts" ""
Write-B64 "src/product/pricing/pricing.ts" ""
Write-B64 "tests/unit/balance.test.ts" ""
Write-B64 "tests/unit/productDomain.test.ts" ""
Write-B64 "tests/integration/pgRepositories.pg.test.ts" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Installed. Expected: 892 passed + 1 skipped, 420 guards." -ForegroundColor Green
